<?php
require_once __DIR__.'/../includes/functions.php';require_role('mentor','admin');require_once __DIR__.'/../config/database.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('mentor/dashboard.php');verify_csrf();$evidenceId=(int)($_POST['evidence_id']??0);$decision=$_POST['decision']??'';$level=(int)($_POST['verified_level']??0);$feedback=trim($_POST['reviewer_feedback']??'');$allowed=['verified','changes_requested','rejected'];if(!in_array($decision,$allowed,true)){$decision='changes_requested';}$st=$pdo->prepare('SELECT evidence_id,user_id,skill_id,project_id,status FROM evidence_submissions WHERE evidence_id=?');$st->execute([$evidenceId]);$evidence=$st->fetch();if(!$evidence){flash('Evidence submission not found.','error');redirect('mentor/dashboard.php');}if((int)$evidence['user_id']===(int)current_user()['user_id']){flash('You cannot review your own evidence submission.','error');redirect('mentor/dashboard.php');}
$pdo->beginTransaction();try{$st=$pdo->prepare('UPDATE evidence_submissions SET status=? WHERE evidence_id=?');$st->execute([$decision,$evidenceId]);$st=$pdo->prepare('INSERT INTO evidence_reviews (evidence_id,reviewer_id,decision,reviewer_feedback) VALUES (?,?,?,?)');$st->execute([$evidenceId,(int)current_user()['user_id'],$decision,$feedback?:null]);if($decision==='verified'){$level=max(1,min(5,$level));$st=$pdo->prepare('INSERT INTO user_skills (user_id,skill_id,self_assessed_level,verified_level,last_assessed_at) VALUES (?,?,0,?,NOW()) ON DUPLICATE KEY UPDATE verified_level=GREATEST(verified_level,VALUES(verified_level))');$st->execute([(int)$evidence['user_id'],(int)$evidence['skill_id'],$level]);if(!empty($evidence['project_id']))award_achievement($pdo,(int)$evidence['user_id'],'FIRST_PROJECT');}
$pdo->commit();$title=$decision==='verified'?'Evidence verified':($decision==='rejected'?'Evidence not accepted':'Changes requested');create_notification($pdo,(int)$evidence['user_id'],$title,$feedback?:'Your evidence submission has been reviewed. Open your evidence page to see its updated status.','evidence','evidence/index.php');flash('Review saved successfully.');redirect('mentor/dashboard.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Evidence review error: '.$e->getMessage());flash('Could not save the review. Please try again.','error');redirect('mentor/dashboard.php');}
